// Generates src/connectors/registry.generated.ts from the connector modules in
// src/connectors/. A module is a connector when it has a top-level
// `export const connector` (of type Connector). Its file name must equal the
// connector id, so the registry is sorted by id.
//
// The generated file is not checked in: it is rebuilt before build, typecheck,
// lint and test, so connector PRs never edit a shared file.
//
// Usage: node scripts/gen-connectors.mjs          write the registry
//        node scripts/gen-connectors.mjs --check  exit 1 if it is missing or stale
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
export const CONNECTORS_DIR = join(ROOT, "src", "connectors");
export const OUTPUT = join(CONNECTORS_DIR, "registry.generated.ts");

/** Files in src/connectors/ that are never registered, even if they export `connector`. */
export const EXCLUDED = new Set(["types.ts", "index.ts", "detect.ts", "example.ts"]);

const EXPORT_RE = /^export const connector\b/m;
const ID_RE = /^[a-z][a-z0-9-]*$/;

/**
 * Whether a file in src/connectors/ may be a connector. Everything else
 * (non-TS files, declarations, generated files, EXCLUDED, `_*.ts` helpers) is
 * ignored on purpose.
 * @param {string} file
 * @returns {boolean}
 */
export function isCandidateFile(file) {
  if (!file.endsWith(".ts") || file.endsWith(".d.ts") || file.endsWith(".generated.ts")) return false;
  return !EXCLUDED.has(file) && !file.startsWith("_");
}

/**
 * @param {string} [dir]
 * @returns {string[]} connector ids (file names without `.ts`), sorted
 */
export function discoverConnectors(dir = CONNECTORS_DIR) {
  const ids = [];
  for (const file of readdirSync(dir)) {
    if (!isCandidateFile(file)) continue;
    if (!EXPORT_RE.test(readFileSync(join(dir, file), "utf8"))) continue;
    const id = file.slice(0, -".ts".length);
    if (!ID_RE.test(id)) throw new Error(`gen-connectors: invalid connector file name "${file}" (use the lower-case id)`);
    ids.push(id);
  }
  return ids.sort();
}

/**
 * @param {readonly string[]} ids
 * @returns {string}
 */
export function renderRegistry(ids) {
  const alias = (/** @type {string} */ id) => id.replace(/-([a-z0-9])/g, (_m, c) => String(c).toUpperCase());
  const lines = [
    "// GENERATED by scripts/gen-connectors.mjs. Do not edit; do not commit.",
    "// Add a connector by creating src/connectors/<id>.ts with `export const connector`.",
    ...ids.map((id) => `import { connector as ${alias(id)} } from "./${id}.js";`),
    'import type { Connector } from "./types.js";',
    "",
    `export const registered: readonly Connector[] = [${ids.map(alias).join(", ")}];`,
    "",
  ];
  return lines.join("\n");
}

/** Writes the registry if it is missing or stale. Used by the CLI entry and by Vitest's globalSetup. */
export function writeRegistry() {
  const expected = renderRegistry(discoverConnectors());
  const current = existsSync(OUTPUT) ? readFileSync(OUTPUT, "utf8") : "";
  if (current !== expected) writeFileSync(OUTPUT, expected);
}

function run() {
  if (!process.argv.includes("--check")) {
    writeRegistry();
    return;
  }
  const current = existsSync(OUTPUT) ? readFileSync(OUTPUT, "utf8") : "";
  if (current !== renderRegistry(discoverConnectors())) {
    console.error("src/connectors/registry.generated.ts is stale. Run: node scripts/gen-connectors.mjs");
    process.exitCode = 1;
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) run();
